16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    private String email;
62	
63	    @Column(name = "postcode")
64	    private String postcode;
65	
66	    @Column(name = "registration_date")
67	    private LocalDate registrationDate;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    @Column(name = "household_size")
82	    private Integer householdSize;
83	
84	    @Column(name = "membership_points")
85	    private Integer membershipPoints;
86	
87	    @Column(name = "membership_level")
88	    private Integer membershipLevel;
89	
90	    @Column(name = "bulk_signup_warning")
91	    private Boolean bulkSignupWarning;
92	
93	    @Column(name = "possible_duplicate")
94	    private Boolean possibleDuplicate;
95	
96	    @Column(name = "possible_duplicate_of")
97	    private Integer possibleDuplicateOf;
98	
99	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
100	    private Set<Pet> pets;
101	
102	    public String getTitle() {
103	        return this.title;
104	    }
105	
106	    public void setTitle(String title) {
107	        this.title = title;
108	    }
109	
110	    /**
111	     * The owner's salutation, derived on read from the owner's {@link #title} and last
112	     * name: {@code "<title> <lastName>"} when a title has been supplied, or just the last
113	     * name when it has not.
114	     */
115	    @Transient
116	    public String getSalutation() {
117	        if (this.title == null || this.title.isBlank()) {
118	            return getLastName();
119	        }
120	        return this.title + " " + getLastName();
121	    }
122	
123	    public String getAddress() {
124	        return this.address;
125	    }
126	
127	    public void setAddress(String address) {
128	        this.address = address;
129	    }
130	
131	    /**
132	     * The first line of the owner's structured address, when supplied. Preferred over the
133	     * flat {@link #getAddress() address} and used to compose it; {@code null} for owners
134	     * created from the flat address form.
135	     */
136	    public String getAddressLine1() {
137	        return this.addressLine1;
138	    }
139	
140	    public void setAddressLine1(String addressLine1) {
141	        this.addressLine1 = addressLine1;
142	    }
143	
144	    /**
145	     * The optional second line of the owner's structured address; {@code null} when absent.
146	     * When present it is appended to {@link #getAddressLine1() addressLine1} to compose the
147	     * {@link #getAddress() address}.
148	     */
149	    public String getAddressLine2() {
150	        return this.addressLine2;
151	    }
152	
153	    public void setAddressLine2(String addressLine2) {
154	        this.addressLine2 = addressLine2;
155	    }
156	
157	    public String getCity() {
158	        return this.city;
159	    }
160	
161	    public void setCity(String city) {
162	        this.city = city;
163	    }
164	
165	    public String getTelephone() {
166	        return this.telephone;
167	    }
168	
169	    public void setTelephone(String telephone) {
170	        this.telephone = telephone;
171	    }
172	
173	    /**
174	     * The owner's stored E.164 {@link #telephone} formatted for humans: the country code, a
175	     * space, then the national digits grouped in threes, e.g. {@code "+61 412 345 678"}.
176	     * Derived on read; {@code null} until a telephone has been set.
177	     */
178	    @Transient
179	    public String getTelephoneDisplay() {
180	        return TelephoneDisplay.format(this.telephone);
181	    }
182	
183	    public String getEmail() {
184	        return this.email;
185	    }
186	
187	    public void setEmail(String email) {
188	        this.email = email;
189	    }
190	
191	    public String getPostcode() {
192	        return this.postcode;
193	    }
194	
195	    public void setPostcode(String postcode) {
196	        this.postcode = postcode;
197	    }
198	
199	    public LocalDate getRegistrationDate() {
200	        return this.registrationDate;
201	    }
202	
203	    public void setRegistrationDate(LocalDate registrationDate) {
204	        this.registrationDate = registrationDate;
205	    }
206	
207	    public LocalDate getBirthDate() {
208	        return this.birthDate;
209	    }
210	
211	    public void setBirthDate(LocalDate birthDate) {
212	        this.birthDate = birthDate;
213	    }
214	
215	    /**
216	     * The owner's {@link AgeBand age band} as of their {@link #registrationDate}, derived on
217	     * read from the owner's {@link #birthDate}. {@code null} until both the birth date and the
218	     * registration date have been supplied.
219	     */
220	    @Transient
221	    public String getAgeBand() {
222	        if (this.birthDate == null || this.registrationDate == null) {
223	            return null;
224	        }
225	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
226	    }
227	
228	    public String getCustomerCode() {
229	        return this.customerCode;
230	    }
231	
232	    public void setCustomerCode(String customerCode) {
233	        this.customerCode = customerCode;
234	    }
235	
236	    /**
237	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where
238	     * {@code YY} is the last two digits of the {@code registrationDate} year, e.g.
239	     * {@code "NSW-1A2B3C4D-M26"}. Derived from the owner's own fields; {@code null} until
240	     * both the customer code and registration date have been assigned.
241	     */
242	    @Transient
243	    public String getMembershipNumber() {
244	        if (this.customerCode == null || this.registrationDate == null) {
245	            return null;
246	        }
247	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
248	    }
249	
250	    /**
251	     * The owner's check digit: a single {@link Luhn} check digit computed over the digits
252	     * of the owner's {@link #customerCode}. {@code null} until the customer code has been
253	     * assigned.
254	     */
255	    @Transient
256	    public Integer getCheckDigit() {
257	        if (this.customerCode == null) {
258	            return null;
259	        }
260	        return Luhn.checkDigit(this.customerCode);
261	    }
262	
263	    /**
264	     * The owner's region: the canonical region derived from the owner's {@link #postcode}
265	     * via the fixed {@link RegionPostcodeTable}, falling back to the owner's {@link #city}
266	     * via the fixed {@link CityRegionTable} when the postcode is absent or in no known
267	     * range, or {@code "UNKNOWN"} when neither yields a region. This is the {@code REGION}
268	     * segment of the owner's {@link #getCustomerCode() customer code}.
269	     */
270	    @Transient
271	    public String getRegion() {
272	        return RegionPostcodeTable.regionOf(this.postcode)
273	            .orElseGet(() -> CityRegionTable.regionOf(this.city));
274	    }
275	
276	    /**
277	     * The owner's locality, read from its region-and-hash identity: the {@code REGION}
278	     * segment (everything before the first {@code '-'}) of the owner's
279	     * {@link #getCustomerCode() customer code}. Falls back to the owner's live
280	     * {@link #getRegion() region} until a customer code has been assigned.
281	     */
282	    @Transient
283	    public String getLocality() {
284	        if (this.customerCode == null) {
285	            return getRegion();
286	        }
287	        int dash = this.customerCode.indexOf('-');
288	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
289	    }
290	
291	    /**
292	     * The owner's IANA timezone name, derived on read from the owner's
293	     * {@link #getLocality() locality} via the fixed {@link RegionTimezoneTable}, e.g.
294	     * {@code "Australia/Sydney"} for {@code NSW}. {@code null} when the locality has no
295	     * timezone in the table.
296	     */
297	    @Transient
298	    public String getTimezone() {
299	        return RegionTimezoneTable.timezoneOf(getLocality());
300	    }
301	
302	    /**
303	     * The owner's preferred contact channel, derived on read from the owner's own
304	     * fields: {@code "EMAIL"} when the owner has an email address, otherwise
305	     * {@code "PHONE"}.
306	     */
307	    @Transient
308	    public String getContactPreference() {
309	        return (this.email == null || this.email.isBlank()) ? "PHONE" : "EMAIL";
310	    }
311	
312	    /**
313	     * The owner's identity key: the single value used to detect duplicate owners on
314	     * create. It joins the owner's (already normalized) telephone, email and household id
315	     * with {@code '|'} — {@code <telephone>|<email>|<householdId>} — a missing email or
316	     * household id contributing an empty segment. Two owners are duplicates only when
317	     * their whole identity keys are equal.
318	     */
319	    @Transient
320	    public String getIdentityKey() {
321	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
322	    }
323	
324	    private static String orEmpty(String value) {
325	        return value == null ? "" : value;
326	    }
327	
328	    public String getHouseholdId() {
329	        return this.householdId;
330	    }
331	
332	    public void setHouseholdId(String householdId) {
333	        this.householdId = householdId;
334	    }
335	
336	    public Integer getNamesakeCount() {
337	        return this.namesakeCount;
338	    }
339	
340	    public void setNamesakeCount(Integer namesakeCount) {
341	        this.namesakeCount = namesakeCount;
342	    }
343	
344	    public Integer getHouseholdSize() {
345	        return this.householdSize;
346	    }
347	
348	    public void setHouseholdSize(Integer householdSize) {
349	        this.householdSize = householdSize;
350	    }
351	
352	    /**
353	     * The owner's membership points, assigned on create by tallying the owner's standing:
354	     * points for having an email address, for having no namesakes, for a large household and
355	     * for tenure (see {@code MembershipLevelAssigner}). The points determine the owner's
356	     * {@link #getMembershipLevel() membership level}.
357	     */
358	    public Integer getMembershipPoints() {
359	        return this.membershipPoints;
360	    }
361	
362	    public void setMembershipPoints(Integer membershipPoints) {
363	        this.membershipPoints = membershipPoints;
364	    }
365	
366	    /**
367	     * The owner's membership level, a number from 1 to 4 assigned on create by banding the
368	     * owner's {@link #getMembershipPoints() membership points} (see
369	     * {@code MembershipLevelAssigner}).
370	     */
371	    public Integer getMembershipLevel() {
372	        return this.membershipLevel;
373	    }
374	
375	    public void setMembershipLevel(Integer membershipLevel) {
376	        this.membershipLevel = membershipLevel;
377	    }
378	
379	    public Boolean getBulkSignupWarning() {
380	        return this.bulkSignupWarning;
381	    }
382	
383	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
384	        this.bulkSignupWarning = bulkSignupWarning;
385	    }
386	
387	    /**
388	     * Whether this owner, when created, softly matched an already-stored owner: one that
389	     * shares its last name and postcode but carries a different telephone. Assigned on
390	     * create; when {@code true}, {@link #getPossibleDuplicateOf()} identifies the matched
391	     * owner.
392	     */
393	    public Boolean getPossibleDuplicate() {
394	        return this.possibleDuplicate;
395	    }
396	
397	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
398	        this.possibleDuplicate = possibleDuplicate;
399	    }
400	
401	    /**
402	     * The id of the already-stored owner this owner softly matched on create (same last
403	     * name and postcode, different telephone), or {@code null} when it matched none.
404	     */
405	    public Integer getPossibleDuplicateOf() {
406	        return this.possibleDuplicateOf;
407	    }
408	
409	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
410	        this.possibleDuplicateOf = possibleDuplicateOf;
411	    }
412	
413	    protected Set<Pet> getPetsInternal() {
414	        if (this.pets == null) {
415	            this.pets = new HashSet<>();
416	        }
417	        return this.pets;
418	    }
419	
420	    protected void setPetsInternal(Set<Pet> pets) {
421	        this.pets = pets;
422	    }
423	
424	    public List<Pet> getPets() {
425	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
426	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
427	        return Collections.unmodifiableList(sortedPets);
428	    }
429	
430	    public void setPets(List<Pet> pets) {
431	        this.pets = new HashSet<>(pets);
432	    }
433	
434	    public void addPet(Pet pet) {
435	        getPetsInternal().add(pet);
436	        pet.setOwner(this);
437	    }
438	
439	    /**
440	     * Return the Pet with the given name, or null if none found for this Owner.
441	     *
442	     * @param name to test
443	     * @return true if pet name is already in use
444	     */
445	    public Pet getPet(String name) {
446	        return getPet(name, false);
447	    }
448	
449	    /**
450	     * Return the Pet with the given name, or null if none found for this Owner.
451	     *
452	     * @param name to test
453	     * @return true if pet name is already in use
454	     */
455	    public Pet getPet(String name, boolean ignoreNew) {
456	        name = name.toLowerCase();
457	        for (Pet pet : getPetsInternal()) {
458	            if (!ignoreNew || !pet.isNew()) {
459	                String compName = pet.getName();
460	                compName = compName.toLowerCase();
461	                if (compName.equals(name)) {
462	                    return pet;
463	                }
464	            }
465	        }
466	        return null;
467	    }
468	
469	    public Pet getPet(Integer petId) {
470	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
471	    }
472	
473	    @Override
474	    public String toString() {
475	        return new ToStringCreator(this)
476	
477	            .append("id", this.getId())
478	            .append("new", this.isNew())
479	            .append("lastName", this.getLastName())
480	            .append("firstName", this.getFirstName())
481	            .append("address", this.address)
482	            .append("city", this.city)
483	            .append("telephone", this.telephone)
484	            .append("email", this.email)
485	            .append("registrationDate", this.registrationDate)
486	            .append("customerCode", this.customerCode)
487	            .toString();
488	    }
489	}
