17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.controller.BulkSignupWarningAssigner;
33	import org.springframework.samples.petclinic.rest.controller.CityCapacityChecker;
34	import org.springframework.samples.petclinic.rest.controller.CustomerCodeAssigner;
35	import org.springframework.samples.petclinic.rest.controller.DailyRegistrationLimiter;
36	import org.springframework.samples.petclinic.rest.controller.HouseholdAssigner;
37	import org.springframework.samples.petclinic.rest.controller.HouseholdDuplicateChecker;
38	import org.springframework.samples.petclinic.rest.controller.HouseholdSizeAssigner;
39	import org.springframework.samples.petclinic.rest.controller.IdentityDuplicateChecker;
40	import org.springframework.samples.petclinic.rest.controller.MembershipLevelAssigner;
41	import org.springframework.samples.petclinic.rest.controller.NamesakeCounter;
42	import org.springframework.samples.petclinic.rest.controller.OwnerCreationAuditLogger;
43	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
44	import org.springframework.samples.petclinic.rest.controller.PossibleDuplicateAssigner;
45	import org.springframework.samples.petclinic.rest.controller.RegistrationDateAssigner;
46	import org.springframework.samples.petclinic.rest.controller.RegistrationDateValidator;
47	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
48	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.PetDto;
50	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
53	import org.springframework.samples.petclinic.service.ClinicService;
54	import org.springframework.security.access.prepost.PreAuthorize;
55	import org.springframework.web.bind.WebDataBinder;
56	import org.springframework.web.bind.annotation.CrossOrigin;
57	import org.springframework.web.bind.annotation.InitBinder;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    private final OwnerFieldsValidator ownerFieldsValidator;
82	
83	    private final RegistrationDateValidator registrationDateValidator;
84	
85	    private final RegistrationDateAssigner registrationDateAssigner;
86	
87	    private final CustomerCodeAssigner customerCodeAssigner;
88	
89	    private final HouseholdDuplicateChecker householdDuplicateChecker;
90	
91	    private final IdentityDuplicateChecker identityDuplicateChecker;
92	
93	    private final HouseholdAssigner householdAssigner;
94	
95	    private final HouseholdSizeAssigner householdSizeAssigner;
96	
97	    private final NamesakeCounter namesakeCounter;
98	
99	    private final MembershipLevelAssigner membershipLevelAssigner;
100	
101	    private final CityCapacityChecker cityCapacityChecker;
102	
103	    private final DailyRegistrationLimiter dailyRegistrationLimiter;
104	
105	    private final BulkSignupWarningAssigner bulkSignupWarningAssigner;
106	
107	    private final OwnerCreationAuditLogger ownerCreationAuditLogger;
108	
109	    private final PossibleDuplicateAssigner possibleDuplicateAssigner;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper,
115	                                 OwnerFieldsValidator ownerFieldsValidator,
116	                                 RegistrationDateValidator registrationDateValidator,
117	                                 RegistrationDateAssigner registrationDateAssigner,
118	                                 CustomerCodeAssigner customerCodeAssigner,
119	                                 HouseholdDuplicateChecker householdDuplicateChecker,
120	                                 IdentityDuplicateChecker identityDuplicateChecker,
121	                                 HouseholdAssigner householdAssigner,
122	                                 HouseholdSizeAssigner householdSizeAssigner,
123	                                 NamesakeCounter namesakeCounter,
124	                                 MembershipLevelAssigner membershipLevelAssigner,
125	                                 CityCapacityChecker cityCapacityChecker,
126	                                 DailyRegistrationLimiter dailyRegistrationLimiter,
127	                                 BulkSignupWarningAssigner bulkSignupWarningAssigner,
128	                                 OwnerCreationAuditLogger ownerCreationAuditLogger,
129	                                 PossibleDuplicateAssigner possibleDuplicateAssigner) {
130	        this.clinicService = clinicService;
131	        this.ownerMapper = ownerMapper;
132	        this.petMapper = petMapper;
133	        this.visitMapper = visitMapper;
134	        this.ownerFieldsValidator = ownerFieldsValidator;
135	        this.registrationDateValidator = registrationDateValidator;
136	        this.registrationDateAssigner = registrationDateAssigner;
137	        this.customerCodeAssigner = customerCodeAssigner;
138	        this.householdDuplicateChecker = householdDuplicateChecker;
139	        this.identityDuplicateChecker = identityDuplicateChecker;
140	        this.householdAssigner = householdAssigner;
141	        this.householdSizeAssigner = householdSizeAssigner;
142	        this.namesakeCounter = namesakeCounter;
143	        this.membershipLevelAssigner = membershipLevelAssigner;
144	        this.cityCapacityChecker = cityCapacityChecker;
145	        this.dailyRegistrationLimiter = dailyRegistrationLimiter;
146	        this.bulkSignupWarningAssigner = bulkSignupWarningAssigner;
147	        this.ownerCreationAuditLogger = ownerCreationAuditLogger;
148	        this.possibleDuplicateAssigner = possibleDuplicateAssigner;
149	    }
150	
151	    @InitBinder("ownerFieldsDto")
152	    void initOwnerFieldsBinder(WebDataBinder binder) {
153	        binder.addValidators(ownerFieldsValidator, registrationDateValidator);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
159	        Collection<Owner> owners;
160	        if (lastName != null) {
161	            owners = this.clinicService.findOwnerByLastName(lastName);
162	        } else {
163	            owners = this.clinicService.findAllOwners();
164	        }
165	        if (owners.isEmpty()) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
174	        Owner owner = this.clinicService.findOwnerById(ownerId);
175	        if (owner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
184	        HttpHeaders headers = new HttpHeaders();
185	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
186	        this.registrationDateAssigner.assign(owner);
187	        if (this.cityCapacityChecker.isCityAtCapacity(owner)) {
188	            return new ResponseEntity<>(HttpStatus.CONFLICT);
189	        }
190	        if (this.dailyRegistrationLimiter.isDailyLimitReached(owner.getRegistrationDate())) {
191	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
192	        }
193	        this.householdAssigner.assign(owner);
194	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
195	        boolean householdDuplicate = this.householdDuplicateChecker.isDuplicate(owner);
196	        if (householdDuplicate && !sharesHousehold) {
197	            return new ResponseEntity<>(HttpStatus.CONFLICT);
198	        }
199	        if (this.identityDuplicateChecker.isDuplicate(owner)) {
200	            return new ResponseEntity<>(HttpStatus.CONFLICT);
201	        }
202	        boolean declaredHouseholdMember = householdDuplicate && sharesHousehold;
203	        this.householdSizeAssigner.assign(owner);
204	        this.customerCodeAssigner.assign(owner);
205	        this.namesakeCounter.assign(owner);
206	        this.membershipLevelAssigner.assign(owner);
207	        this.bulkSignupWarningAssigner.assign(owner);
208	        this.possibleDuplicateAssigner.assign(owner, declaredHouseholdMember);
209	        this.clinicService.saveOwner(owner);
210	        this.ownerCreationAuditLogger.logCreated(owner);
211	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
212	        headers.setLocation(UriComponentsBuilder.newInstance()
213	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
214	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
215	    }
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
220	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
221	        if (currentOwner == null) {
222	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	        }
224	        currentOwner.setAddress(ownerFieldsDto.getAddress());
225	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
226	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
227	        currentOwner.setCity(ownerFieldsDto.getCity());
228	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
229	        currentOwner.setLastName(ownerFieldsDto.getLastName());
230	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
231	        currentOwner.setEmail(ownerFieldsDto.getEmail());
232	        this.clinicService.saveOwner(currentOwner);
233	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
234	    }
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Transactional
238	    @Override
239	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
240	        Owner owner = this.clinicService.findOwnerById(ownerId);
241	        if (owner == null) {
242	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
243	        }
244	        this.clinicService.deleteOwner(owner);
245	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
249	    @Override
250	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
251	        Owner owner = this.clinicService.findOwnerById(ownerId);
252	        if (owner == null) {
253	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	        }
255	        HttpHeaders headers = new HttpHeaders();
256	        Pet pet = petMapper.toPet(petFieldsDto);
257	        owner.setId(ownerId);
258	        pet.setOwner(owner);
259	        pet.getType().setName(null);
260	        this.clinicService.savePet(pet);
261	        PetDto petDto = petMapper.toPetDto(pet);
262	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
263	            .buildAndExpand(pet.getId()).toUri());
264	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
265	    }
266	
267	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
268	    @Override
269	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
270	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
271	        if (currentOwner != null) {
272	            Pet currentPet = this.clinicService.findPetById(petId);
273	            if (currentPet != null) {
274	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
275	                currentPet.setName(petFieldsDto.getName());
276	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
277	                this.clinicService.savePet(currentPet);
278	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
279	            }
280	        }
281	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
282	    }
283	
284	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
285	    @Override
286	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
287	        HttpHeaders headers = new HttpHeaders();
288	        Visit visit = visitMapper.toVisit(visitFieldsDto);
289	        Pet pet = new Pet();
290	        pet.setId(petId);
291	        visit.setPet(pet);
292	        this.clinicService.saveVisit(visit);
293	        VisitDto visitDto = visitMapper.toVisitDto(visit);
294	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
295	            .buildAndExpand(visit.getId()).toUri());
296	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
297	    }
298	
299	
300	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
301	    @Override
302	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
303	        Owner owner = this.clinicService.findOwnerById(ownerId);
304	        if (owner != null) {
305	            Pet pet = owner.getPet(petId);
306	            if (pet != null) {
307	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
308	            }
309	        }
310	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
311	    }
312	}
